const arrow='<i aria-hidden="true">→</i>';
const rv=(k,d)=>` data-rv="${k||'up'}"${d?` style="--d:${d}ms"`:''}`;
const sectionHead=(k,t,sub,link)=>`<div class="sh"><div><span class="kick"${rv('up')}>${k}</span><h2 data-rv="words">${t}</h2>${sub?`<p${rv('up',220)}>${sub}</p>`:''}</div>${link?`<a class="more"${rv('up',240)} href="${link[0]}">${link[1]} ${arrow}</a>`:''}</div>`;

/* ---------- Prochains rendez-vous ---------- */
const DOW={Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6},fmt=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'short',hour:'numeric',minute:'numeric',second:'numeric',hourCycle:'h23'});
function nowNY(){const p={};fmt.formatToParts(new Date()).forEach(x=>p[x.type]=x.value);return DOW[p.weekday]*86400+ +p.hour*3600+ +p.minute*60+ +p.second}
const sec=(d,t)=>{const a=t.split(':');return d*86400+a[0]*3600+a[1]*60},WK=604800;
S.upcoming=function(n){const now=nowNY(),all=[];S.schedule.forEach(it=>it.days.forEach(d=>{const st=sec(d,it.s),en=sec(d,it.e);all.push({it,d,secs:(st-now+WK)%WK,live:now>=st&&now<en})}));all.sort((a,b)=>(b.live-a.live)||(a.secs-b.secs));const seen={},out=[];for(const x of all){if(seen[x.it.id])continue;seen[x.it.id]=1;out.push(x);if(out.length===n)break}return out};
const DF=['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'],DE=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const dayName=d=>T(DF[d],DE[d]),days=it=>it.days.length===5?T('Lun. à ven.','Mon. to Fri.'):dayName(it.days[0]),clock=t=>{const a=t.split(':'),h=+a[0],m=a[1];if(S.lang==='en')return (h%12||12)+(m!=='00'?':'+m:'')+' '+(h>=12?'PM':'AM');return h+' h'+(m!=='00'?' '+m:'')};
const p2=n=>(n<10?'0':'')+n;
function paintNext(){const n=S.upcoming(1)[0],s=n.secs,d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60),x=s%60;
  $$('[data-next]').forEach(el=>{const k=el.dataset.next;if(k==='title')el.textContent=n.it[S.lang];if(k==='when')el.textContent=dayName(n.d)+', '+clock(n.it.s);if(k==='count')el.textContent=n.live?T('En cours','Happening now'):T('dans ','in ')+(d?d+T(' j ',' d '):'')+p2(h)+' h '+p2(m)+' min'});
  const set=(k,v)=>$$(`[data-cd="${k}"]`).forEach(e=>e.textContent=v);set('d',d);set('h',p2(h));set('m',p2(m));set('s',p2(x));
  $$('[data-next-id]').forEach(el=>el.classList.toggle('is-next',el.dataset.nextId===n.it.id))}

/* ---------- En-tête, menu, pied ---------- */
const isCur=h=>{const r=location.hash||'#/';return h==='#/'?(r==='#/'||r===''):r.startsWith(h)};
const langs=()=>`<div class="langs" role="group" aria-label="${T('Langue','Language')}"><button data-lang="fr" class="${S.lang==='fr'?'on':''}" aria-pressed="${S.lang==='fr'}">FR</button><button data-lang="en" class="${S.lang==='en'?'on':''}" aria-pressed="${S.lang==='en'}">EN</button></div>`;
const header=()=>`<header class="hd" id="hd"><div class="hd-in"><a class="brand" href="#/"><img src="${IMG}logo.png" alt=""><span>Mission For Christ<br>International</span></a><nav class="mainnav" aria-label="${T('Navigation principale','Main navigation')}">${S.nav.map(n=>n.sub?`<div class="nav-i${n.sub.some(x=>isCur(x[2]))?' cur':''}"><button aria-haspopup="true">${T(n.fr,n.en)}<svg viewBox="0 0 10 10" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M1.500 3.500L5 7l3.500-3.500"/></svg></button><div class="sub">${n.sub.map(x=>`<a href="${x[2]}">${T(x[0],x[1])}</a>`).join('')}</div></div>`:`<div class="nav-i${isCur(n.h)?' cur':''}"><a href="${n.h}">${T(n.fr,n.en)}</a></div>`).join('')}</nav>${langs()}<a class="btn gold hd-give" href="#/don">${T('Faire un don','Give')}</a><button class="burger" data-menu aria-label="Menu"><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.900" stroke-linecap="round" aria-hidden="true"><path d="M3 6.500h14M3 13.500h14"/></svg></button></div><div class="prog" id="prog"></div></header><div class="hd-sp" aria-hidden="true"></div>`;
const drawer=()=>`<div class="drawer"><div class="drawer-in" role="dialog" aria-label="Menu"><div class="drawer-top">${langs()}<button class="burger" style="display:grid" data-menu aria-label="${T('Fermer','Close')}"><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.900" stroke-linecap="round" aria-hidden="true"><path d="M5 5l10 10M15 5L5 15"/></svg></button></div><div>${S.nav.map(n=>n.sub?`<h4>${T(n.fr,n.en)}</h4>${n.sub.map(x=>`<a class="dl" href="${x[2]}">${T(x[0],x[1])}</a>`).join('')}`:`<a class="dl" href="${n.h}">${T(n.fr,n.en)}</a>`).join('')}</div><a class="btn gold" href="#/don">${T('Faire un don','Give')}</a></div></div>`;
const newsletter=()=>`<section class="nlw"><div class="wrap"><div class="nl"${rv('zoom')}><div><h2>${T('Restez informé','Stay informed')}</h2><p>${T("Recevez les annonces et les événements de l'église, par e-mail ou par WhatsApp.",'Receive church announcements and events, by email or WhatsApp.')}</p></div><div><form data-demo="news"><input type="email" required aria-label="${T('Votre adresse e-mail','Your email address')}" placeholder="${T('Votre adresse e-mail','Your email address')}"><button class="btn gold">${T("S'abonner",'Subscribe')}</button></form><div class="nl-or"><span>${T('ou','or')}</span><a class="nl-wa" href="${waOpt()}" target="_blank" rel="noopener">${I.wa}${T('Recevoir sur WhatsApp','Get it on WhatsApp')}</a></div><small>${T('Démonstration : aucune inscription n’est enregistrée.','Demo: no sign-up is saved.')}</small></div></div></div></section>`;
const footer=()=>{const c=S.contact;return `<footer class="ft"><div class="wrap"><div class="ft-g"><div class="ft-brand"><a class="brand" href="#/"><img src="${IMG}logo.png" alt=""><span>Mission For Christ<br>International</span></a><p style="opacity:.82;max-width:26em">${T('Jésus-Christ, la clé de la victoire. Cultes en français et en anglais.','Jesus Christ, the key to victory. Services in French and English.')}</p><div class="socs"><a href="${c.facebook}" target="_blank" rel="noopener" aria-label="Facebook">${I.fb}</a><a href="${c.youtube}" target="_blank" rel="noopener" aria-label="YouTube">${I.yt}</a><a href="${c.whatsapp}" target="_blank" rel="noopener" aria-label="WhatsApp">${I.wa}</a></div></div>
 <div><b class="h">${T("L'église",'Church')}</b><a class="l" href="#/presentation">${T('Présentation','About us')}</a><a class="l" href="#/leaders">${T('Nos leaders','Leaders')}</a><a class="l" href="#/annexes">${T('Nos annexes','Branches')}</a><a class="l" href="#/activites">${T('Activités et événements','Activities and events')}</a><a class="l" href="#/don">${T('Faire un don','Give')}</a></div>
 <div><b class="h">${T('Médias','Media')}</b><a class="l" href="#/articles">Articles</a><a class="l" href="#/albums">${T('Albums photos','Photo albums')}</a><a class="l" href="#/videos">${T('Vidéos','Videos')}</a><a class="l" href="#/temoignages">${T('Témoignages','Testimonies')}</a></div>
 <div class="ft-contact"><b class="h">Contact</b><a class="l" href="${c.maps}" target="_blank" rel="noopener">${c.address}</a>${c.phones.map(p=>`<a class="l" href="tel:+1${p.replace(/\D/g,'')}">${p}</a>`).join('')}<a class="l" href="mailto:${c.email}">${c.email}</a></div></div><p class="legal">© 2026 Mission For Christ International</p></div></footer>`};
const fab=()=>`<div class="fab"><button class="fab-top" id="top" aria-label="${T('Remonter en haut de la page','Back to top')}"><svg class="pr" viewBox="0 0 50 50" aria-hidden="true"><circle cx="25" cy="25" r="22" id="ring"/></svg>${I.up}</button><a class="fab-wa" href="${S.contact.whatsapp}" target="_blank" rel="noopener" aria-label="${T('Écrire à l’église sur WhatsApp','Message the church on WhatsApp')}">${I.wa}<span>${T('Écrivez-nous sur WhatsApp','Message us on WhatsApp')}</span></a></div>`;

/* ---------- Bannière en carrousel ---------- */
function hero(){const sl=[
 {type:'photo',img:'choeur',pos:'50% 8%',tab:T('Bienvenue','Welcome'),k:T('Bienvenue à Mission For Christ International','Welcome to Mission For Christ International'),h:T('Jésus-Christ, la clé de la <em>victoire</em>','Jesus Christ, the key to <em>victory</em>'),tag:'h1',p:T('Venez adorer avec nous, en français et en anglais, avec le pasteur Edmond Tiede.','Come and worship with us, in French and English, with Pastor Edmond Tiede.'),b:[[T('Nous rendre visite','Plan a visit'),'#/contact','gold'],[T('Nos activités','Our activities'),'#/activites','ghost']]},
 {type:'split',img:'choeur2',tab:T('Culte du dimanche','Sunday service'),k:T('Chaque dimanche','Every Sunday'),h:T('Le culte à <em>14 heures</em>','Service at <em>2 PM</em>'),p:T('8430 Glenmar Road, Ellicott City, Maryland. En français et en anglais.','8430 Glenmar Road, Ellicott City, Maryland. In French and English.'),b:[[T('Voir les activités','See activities'),'#/activites','gold'],[T('Itinéraire','Directions'),S.contact.maps,'ghost']]},
 {type:'photo',img:'dimanche',pos:'50% 22%',tab:T('Dernier album','Latest album'),k:T('En images','In pictures'),h:T('Revivez le culte du <em>27 septembre</em>','Relive the service of <em>September 27</em>'),p:T('Découvrez les photos de nos derniers rassemblements.','See the photos of our latest gatherings.'),b:[[T("Voir l'album",'See the album'),'#/albums/12','gold'],[T('Tous les albums','All albums'),'#/albums','ghost']]},
 {type:'rev',img:'offrande',tab:T('Faire un don','Give'),k:T('Soutenir la mission','Support the mission'),h:T('Dieu aime celui qui donne <em>avec joie</em>','God loves a <em>cheerful giver</em>'),p:T('2 Corinthiens 9:7. Votre don soutient la vie de l’église et sa mission.','2 Corinthians 9:7. Your gift supports the life of the church and its mission.'),b:[[T('Faire un don','Give'),'#/don','gold']]}];
 return `<section class="hero" data-hero aria-roledescription="carrousel" aria-label="${T('Bannières','Banners')}">${sl.map((s,i)=>{const tag=s.tag||'h2',txt=`<div class="hs-txt"><span class="hs-k" style="--i:0">${s.k}</span><${tag} style="--i:1">${s.h}</${tag}><p style="--i:2">${s.p}</p><div class="btns" style="--i:3">${s.b.map(b=>`<a class="btn ${b[2]}" href="${b[1]}"${b[1].startsWith('http')?' target="_blank" rel="noopener"':''}>${b[0]} ${arrow}</a>`).join('')}</div></div>`;
  return s.type==='photo'?`<article class="hs hs--photo${i===0?' on':''}"><div class="hs-bg"><img src="${HERO}${s.img}.jpg" alt="" style="object-position:${s.pos||'50% 30%'}"></div><div class="wrap hs-in">${txt}</div></article>`:`<article class="hs hs--split${s.type==='rev'?' hs--rev':''}"><div class="hs-media"><img src="${HERO}${s.img}.jpg" alt="" style="object-position:${s.pos||'50% 30%'}"></div><div class="wrap hs-in">${txt}</div></article>`}).join('')}
 <div class="hn"><div class="wrap"><div class="hn-tabs" role="tablist">${sl.map((s,i)=>`<button class="hn-tab${i===0?' on':''}" role="tab" aria-selected="${i===0}" aria-label="${T('Bannière','Banner')} ${i+1} : ${s.tab}"><i class="bar"><b></b></i><span><b>0${i+1}</b>${s.tab}</span></button>`).join('')}</div><div class="hn-ar"><button data-hp aria-label="${T('Bannière précédente','Previous banner')}">${I.arrowL}</button><button data-hn aria-label="${T('Bannière suivante','Next banner')}">${I.arrowR}</button></div></div></div><i class="hero-l"></i></section>`}
function initHero(){const r=$('[data-hero]');if(!r)return;const sl=$$('.hs',r),tb=$$('.hn-tab',r),ln=$('.hero-l',r);let i=0,busy=false;
 function go(n,dir){n=(n+sl.length)%sl.length;if(n===i||busy)return;busy=true;const a=sl[i],b=sl[n];dir=dir||(n>i?1:-1);b.style.transition='none';b.classList.add(dir>0?'from-r':'from-l');void b.offsetWidth;b.style.transition='';a.classList.remove('on');a.classList.add('out');b.classList.remove('from-r','from-l');b.classList.add('on');if(ln&&!reduced){ln.className='hero-l';void ln.offsetWidth;ln.classList.add(dir>0?'go-r':'go-l')}
  tb.forEach((t,k)=>{t.classList.toggle('on',k===n);t.setAttribute('aria-selected',k===n)});i=n;setTimeout(()=>{a.classList.remove('out');busy=false},reduced?0:1020)}
 S.goSlide=n=>go(n);tb.forEach((t,k)=>t.addEventListener('click',()=>go(k)));$('[data-hp]',r).onclick=()=>go(i-1,-1);$('[data-hn]',r).onclick=()=>go(i+1,1);
 r.addEventListener('animationend',e=>{if(e.animationName==='hfill')go(i+1,1)});
 let sx=null;r.addEventListener('pointerdown',e=>{if(e.target.closest('a,button'))return;sx=e.clientX});r.addEventListener('pointerup',e=>{if(sx===null)return;const d=e.clientX-sx;sx=null;if(Math.abs(d)>48)go(i+(d<0?1:-1),d<0?1:-1)});
 r.addEventListener('keydown',e=>{if(e.key==='ArrowRight')go(i+1,1);if(e.key==='ArrowLeft')go(i-1,-1)})}

/* ---------- Partage ---------- */
const shareUrl=p=>(/^https?:$/.test(location.protocol)&&!/^(localhost|127\.)/.test(location.hostname)?location.origin+location.pathname:'https://mfcichurch.com/')+'#/'+p;
const albUrl=a=>/^https?:$/.test(location.protocol)&&!/^(localhost|127\.)/.test(location.hostname)?location.origin+location.pathname.replace(/index\.html$/,'')+'a/'+a.id+'/':'https://mfcichurch.com/#/albums/'+a.id;
const share=(title,path,big)=>{const raw=shareUrl(path),u=encodeURIComponent(raw),t=encodeURIComponent(title),a=(h,ic,n)=>`<a href="${h}" target="_blank" rel="noopener" aria-label="${T('Partager sur','Share on')} ${n}" title="${n}" class="s-${n.toLowerCase().replace(/[^a-z]/g,'')}">${ic}</a>`;return `<div class="shr${big?' big':''}"><span class="shr-l">${big?T('Partager','Share'):''}</span>${a('https://www.facebook.com/sharer/sharer.php?u='+u,I.fb,'Facebook')}${a('https://wa.me/?text='+t+'%20'+u,I.wa,'WhatsApp')}${a('https://twitter.com/intent/tweet?text='+t+'&url='+u,I.x,'X')}<a href="mailto:?subject=${t}&body=${u}" aria-label="${T('Envoyer par e-mail','Send by email')}" title="E-mail">${I.mail}</a><button data-copy="${raw}" aria-label="${T('Copier le lien','Copy link')}" title="${T('Copier le lien','Copy link')}">${I.link}</button>${navigator.share?`<button data-native="${raw}" data-title="${title.replace(/"/g,'&quot;')}" aria-label="${T('Partager','Share')}" title="${T('Partager','Share')}">${I.share}</button>`:''}</div>`};
const waOpt=()=>S.contact.whatsapp+'?text='+encodeURIComponent(T('Bonjour, je souhaite recevoir les informations de l’église.','Hello, I would like to receive church news.'));

/* ---------- Blocs de l'accueil ---------- */
const infobar=()=>{const c=S.contact;return `<section class="info"><div class="wrap"><div class="info-g"${rv('up',100)}><a class="info-c" href="#/activites"><span class="ico">${I.clock}</span><span><small>${T('Prochain rendez-vous','Next gathering')}</small><b data-next="title"></b><span class="c" data-next="count"></span></span></a><a class="info-c" href="#/activites"><span class="ico">${I.cal}</span><span><small>${T('Culte du dimanche','Sunday service')}</small><b>${T('Chaque dimanche à 14 h','Every Sunday at 2 PM')}</b></span></a><a class="info-c" href="${c.maps}" target="_blank" rel="noopener"><span class="ico">${I.pin}</span><span><small>${T('Nous trouver','Find us')}</small><b>8430 Glenmar Road, Ellicott City</b></span></a><a class="info-c" href="tel:+14108554242"><span class="ico">${I.phone}</span><span><small>${T('Ligne de prière','Prayer line')}</small><b>${c.line}</b></span></a></div></div></section>`};
const stats=()=>`<div class="stats">${[[3,T('maisons','houses')],[2,T('langues','languages')],[6,T('rendez-vous réguliers','regular gatherings')],[16,T('responsables','leaders')]].map((s,i)=>`<div class="stat" data-stat style="--sd:${i*160}ms"><b data-count="${s[0]}">${s[0]}</b><span>${s[1]}</span></div>`).join('')}</div>`;
const about=()=>`<section class="sec"><div class="wrap ab"><div class="ab-v"><div class="ab-1"${rv('clip')}><img class="pxi" data-px loading="lazy" src="${HERO}assemblee.jpg" alt="${T("L'assemblée en prière",'The congregation in prayer')}"></div><div class="ab-2"${rv('zoom',260)}><img loading="lazy" src="${HERO}table.jpg" alt="${T('Une fidèle à une table dressée','A worshipper at a set table')}"></div><div class="ab-b"${rv('up',420)}><img src="${IMG}logo.png" alt=""><span>${T('Jésus-Christ, la clé de la victoire','Jesus Christ, the key to victory')}</span></div></div><div><span class="kick"${rv('up')}>${T('Bienvenue','Welcome')}</span><h2 data-rv="words">${T('Une famille, en français et en anglais','One family, in French and English')}</h2><p class="lead" style="margin-top:14px"${rv('up',180)}>${T("Mission For Christ International est une église et des ministères installés à Ellicott City, dans le Maryland, avec des annexes à Richmond et au Burundi.",'Mission For Christ International is a church and ministries based in Ellicott City, Maryland, with branches in Richmond and Burundi.')}</p>${stats()}<div class="btns"${rv('up',260)}><a class="btn" href="#/presentation">${T('Découvrir l’église','Discover the church')} ${arrow}</a><a class="btn line" href="#/leaders">${T('Nos leaders','Our leaders')}</a></div></div></div></section>`;
const evCard=(e,i)=>`<article class="ev-c"${rv('up',i*90)}><button class="ev" data-lbs="ev" data-lb="${i}" aria-label="${T("Voir l'affiche",'See the poster')} : ${e[S.lang]}"><div class="ev-i"><img loading="lazy" src="${IMG}${e.img}.jpg" alt=""><div class="ev-d"><b>${e.day}</b><span>${e.mon[S.lang]}</span></div><span class="ev-g"></span><div class="ev-o">${T("Voir l'affiche",'See the poster')} →</div></div><h3><span class="ul">${e[S.lang]}</span></h3><small>${T(e.dfr,e.den)} · ${T(e.pfr,e.pen)}</small></button>${share(e[S.lang],'activites')}</article>`;
const eventsSec=(cls)=>`<section class="sec ${cls||'mist'}"><div class="wrap">${sectionHead(T('Événements','Events'),T('Nos derniers événements','Our latest events'),T('Jeûnes, célébrations et rassemblements de la vie de l’église.','Fasts, celebrations and gatherings in the life of the church.'),cls==='page'?null:['#/activites',T('Toutes les activités','All activities')])}<div class="rail">${S.events.map(evCard).join('')}</div></div></section>`;
const actRow=(id,link)=>{const it=S.schedule.find(x=>x.id===id),tagn=T('Prochain','Next');const inner=`<span class="ac-day">${days(it)}</span><span class="ac-t">${clock(it.s)}</span><span class="ac-n">${it[S.lang]}</span><span class="ac-m" data-next="${''}" data-tag="${tagn}">${it.mode[S.lang]}</span>`.replace(' data-next=""','');return link?`<a class="ac-r" href="#/activites" data-act="${id}" data-next-id="${id}">${inner}</a>`:`<div class="ac-r has-cal" tabindex="0" data-act="${id}" data-next-id="${id}">${inner}<a class="ac-cal" href="${gcal(it)}" target="_blank" rel="noopener" aria-label="${T('Ajouter à mon agenda','Add to my calendar')} : ${it[S.lang]}" title="${T('Ajouter à mon agenda','Add to my calendar')}">${I.cal}</a></div>`};
const actSec=(link)=>{const ids=['sun','mor','tue','wed','thu','fri'];return `<section class="sec navy"><div class="wrap">${sectionHead(T('Activités','Activities'),T('Six rendez-vous chaque semaine','Six gatherings every week'),T('Les heures sont celles du Maryland. La ligne de prière est le ','Times are Maryland time. The prayer line is ')+S.contact.line+'.',link?['#/activites',T('Toutes les activités','All activities')]:null)}<div class="ac"><div class="ac-p"${rv('clip')} id="acp">${ids.map((id,i)=>`<img loading="lazy" data-ai="${id}" class="${i===0?'on':''}" src="${HERO}${ACT[id]}.jpg" alt="">`).join('')}<div class="cd"><small>${T('Prochain rendez-vous','Next gathering')}</small><strong data-next="title"></strong><div class="cd-n"><div><b data-cd="d" style="font-weight:inherit"></b><span>${T('jours','days')}</span></div><div><b data-cd="h" style="font-weight:inherit"></b><span>${T('heures','hours')}</span></div><div><b data-cd="m" style="font-weight:inherit"></b><span>min</span></div><div><b data-cd="s" style="font-weight:inherit"></b><span>sec</span></div></div></div></div><div class="ac-l"${rv('right',120)}>${ids.map(id=>actRow(id,link)).join('')}</div></div></div></section>`};
const leadersSec=()=>`<section class="sec"><div class="wrap">${sectionHead(T('Nos leaders','Our leaders'),T('Celles et ceux qui veillent sur la maison','The people who watch over the house'),'',['#/leaders',T('Voir toute l’équipe','See the whole team')])}<div class="lx" id="lx"${rv('up',80)}>${S.leaders.slice(0,5).map((p,i)=>`<a class="lx-i${i===0?' on':''}" href="#/leaders"><img loading="lazy" src="${IMG}${p[0]}.jpg" alt="${p[1]}"><span class="lx-v">${p[1]}</span><div class="lx-t"><b>${p[1]}</b><span>${T(p[2],p[3])}</span></div></a>`).join('')}</div></div></section>`;
const artFeature=a=>`<article class="af"${rv('left')}><a class="af-l" href="#/articles/${a.slug}" aria-label="${a[S.lang]}"></a><img loading="lazy" src="${HERO}${ARTIMG[a.slug]}.jpg" alt=""><div class="af-s">${share(a[S.lang],'articles/'+a.slug)}</div><div class="af-t"><span class="tag">${a.ref}</span><h3><span class="ul">${a[S.lang]}</span></h3><p style="opacity:.92;max-width:34em">${a.ex[S.lang]}</p><span class="more" style="color:var(--gold);margin-top:6px">${T('Lire le message','Read the message')} ${arrow}</span></div></article>`;
const artRow=(a,i)=>`<a class="ar"${rv('right',i*110)} href="#/articles/${a.slug}"><div class="ar-t"><img loading="lazy" src="${HERO}${ARTIMG[a.slug]}.jpg" alt=""><span class="crt"><span>${arrow}</span></span></div><div><small>${a.ref}</small><h3><span class="ul">${a[S.lang]}</span></h3><p>${a.ex[S.lang]}</p></div></a>`;
const articlesSec=()=>`<section class="sec mist"><div class="wrap">${sectionHead(T('Enseignements','Teaching'),T('Derniers articles','Latest articles'),'',['#/articles',T('Tous les articles','All articles')])}<div class="ar-g">${artFeature(S.articles[0])}<div>${S.articles.slice(1).map(artRow).join('')}</div></div></div></section>`;
const vidItem=(v,i)=>`<button class="vi${i===0?' on':''}" data-vs="${v.id}"><span class="vi-t"><img loading="lazy" src="https://i.ytimg.com/vi/${v.id}/mqdefault.jpg" alt=""></span><span><b>${v.fr}</b><small>${v.d}</small></span></button>`;
const player=(list)=>{const v=list[0];return `<div class="vp" data-player><div${rv('left')}><div class="vp-s" data-vscreen="${v.id}"><img src="https://i.ytimg.com/vi/${v.id}/hqdefault.jpg" alt=""><button class="vp-b" data-vplay aria-label="${T('Lire la vidéo','Play video')}">${I.play}</button></div><div class="vp-c"><h3 data-vt>${v.fr}</h3><small data-vd>${v.d}</small></div></div><div class="vp-l"${rv('right',120)}>${list.map(vidItem).join('')}</div></div>`};
const videosSec=()=>`<section class="sec navy"><div class="wrap">${sectionHead(T('Vidéos','Videos'),T('Revivez nos cultes','Relive our services'),T('Prédications, louanges et exhortations.','Sermons, worship and exhortations.'),['#/videos',T('Toutes les vidéos','All videos')])}${player(S.videos.slice(0,6))}</div></section>`;
const albCard=(a,c,d)=>{const big=/big|a-b/.test(c||''),th=a.photos.slice(0,big?4:2).map(p=>ALB+p[0]).join('|');return `<a class="mo-i alb-c ${c||''}"${rv('up',d||0)} href="#/albums/${a.id}" data-thumbs="${a.photos.length>1?th:''}"><img class="cv" loading="lazy" src="${ALB}a${a.id}-c.jpg" alt=""><span class="mo-st"></span><span class="alb-s" data-albshare="${a.id}" aria-hidden="true" title="${T('Partager cet album','Share this album')}">${I.share}</span><div class="mo-t"><b>${a[S.lang]}</b><span class="c1">${a.count} photo${a.count>1?'s':''}</span><span class="c2">${T("Voir l'album",'See the album')} →</span></div></a>`};
const albumsSec=()=>`<section class="sec"><div class="wrap">${sectionHead(T('Albums photos','Photo albums'),T('La vie de l’église en images','Church life in pictures'),'',['#/albums',T('Tous les albums','All albums')])}<div class="mo">${S.albums.slice(0,5).map((a,i)=>albCard(a,i===0?'big':'',i*80)).join('')}</div></div></section>`;
const homesSec=()=>`<section class="sec mist"><div class="wrap">${sectionHead(T('Nos annexes','Our branches'),T('Une famille, trois maisons','One family, three houses'),'',['#/annexes',T('Toutes nos annexes','All branches')])}<div class="ho">${S.houses.map((h,i)=>`<a class="ho-i"${rv('up',i*100)} href="#/annexes"><img loading="lazy" src="${IMG}${h.img}.jpg" alt="${h[S.lang]}"><div class="ho-t"><h3><span class="ul">${h[S.lang]}</span></h3><p>${T(h.rf,h.re)}</p><div class="ho-m"><div><span>${h.tel}</span></div></div></div></a>`).join('')}</div></div></section>`;
const giveSec=()=>`<section class="gv"><img data-px loading="lazy" src="${HERO}offrande.jpg" alt=""><div class="wrap"><div${rv('left')}><span class="kick" style="color:var(--gold)">${T('Soutenir la mission','Support the mission')}</span><h2>${T('Dieu aime celui qui donne avec joie','God loves a cheerful giver')}</h2><p>${T('2 Corinthiens 9:7. Votre don soutient la vie de l’église et sa mission, ici comme à l’étranger.','2 Corinthians 9:7. Your gift supports the life of the church and its mission, here and abroad.')}</p><div class="btns"><a class="btn gold" href="#/don">${T('Faire un don','Give')} ${arrow}</a></div></div></div></section>`;
const AGD={sun:['20261108','SU'],mor:['20261109','MO,TU,WE,TH,FR'],tue:['20261110','TU'],wed:['20261111','WE'],thu:['20261112','TH'],fri:['20261113','FR']};
const gcal=it=>{const a=AGD[it.id],hm=t=>t.replace(':','')+'00';return 'https://calendar.google.com/calendar/render?action=TEMPLATE&text='+encodeURIComponent(it[S.lang]+' · MFCI')+'&dates='+a[0]+'T'+hm(it.s)+'/'+a[0]+'T'+hm(it.e)+'&ctz=America/New_York&recur='+encodeURIComponent('RRULE:FREQ=WEEKLY;BYDAY='+a[1])+'&location='+encodeURIComponent(S.contact.address)};
