const home=()=>hero()+infobar()+about()+eventsSec()+actSec(true)+leadersSec()+articlesSec()+videosSec()+albumsSec()+homesSec()+widgetsSec()+giveSec();

/* ---------- Pages ---------- */
const ph=(img,t,p,cr)=>`<section class="ph"><img src="${img.includes('/')?img:HERO+img+'.jpg'}" alt="" data-px><div class="wrap">${cr?`<div class="crumb">${cr}</div>`:`<div class="crumb"><a href="#/">${T('Accueil','Home')}</a><span>/</span><span>${t}</span></div>`}<h1 data-rv="words">${t}</h1>${p?`<p${rv('up',240)}>${p}</p>`:''}</div></section>`;
