const V={};
V.presentation=()=>ph('assemblee',T('Présentation','About us'),T('Une église où l’on adore en français et en anglais.','A church worshipping in French and English.'))+`<section class="sec"><div class="wrap split"><div><span class="kick"${rv('up')}>${T('Qui sommes-nous','Who we are')}</span><h2 data-rv="words">${T('Jésus-Christ, la clé de la victoire','Jesus Christ, the key to victory')}</h2><p class="lead" style="margin:14px 0"${rv('up',200)}>${T('Mission For Christ International est une église et des ministères installés à Ellicott City, dans le Maryland, avec des annexes à Richmond et au Burundi.','Mission For Christ International is a church and ministries based in Ellicott City, Maryland, with branches in Richmond and Burundi.')}</p>${stats()}<span class="todo">${T("Le texte actuel de cette page sur le site est du faux texte. L'histoire et la vision de l'église seront écrites ici depuis l'espace admin.",'The current text of this page on the site is placeholder copy. The church’s history and vision will be written here from the admin area.')}</span></div><div class="coin-w"${rv('zoom',120)}><span class="coin-g"></span><img class="coin-f" src="${IMG}logo-hd.webp" alt="${T('Logo de Mission For Christ International','Mission For Christ International logo')}"><canvas id="coin" role="img" aria-label="${T('Logo en 3D : il suit la souris et tourne au clic','3D logo: it follows the mouse and spins on click')}"></canvas><small class="coin-h">${T('Passez la souris, cliquez, faites-le tourner','Hover, click, spin it')}</small></div></div></section><section class="gv qb"><img data-px loading="lazy" src="${HERO}priere.jpg" alt=""><div class="wrap"><div><span class="kick" style="color:var(--gold)"${rv('up')}>${T('Matthieu 28:19','Matthew 28:19')}</span><h2 data-rv="words">${T('Allez, faites de toutes les nations des disciples.','Go ye therefore, and teach all nations.')}</h2></div></div></section><section class="sec mist"><div class="wrap split rev"><div class="fr" style="aspect-ratio:1/1.05"${rv('clip')}><img loading="lazy" src="${IMG}p-edmond.jpg" alt="Pasteur Edmond Pierre Tiede" style="object-position:50% 14%"></div><div${rv('right')}><span class="kick">${T('Pasteur principal','Senior Pastor')}</span><h2>Pasteur Edmond Pierre Tiede</h2><div class="btns" style="margin-top:20px"><a class="btn" href="#/leaders">${T('Voir tous les leaders','See all leaders')} ${arrow}</a><a class="btn line" href="#/annexes">${T('Nos annexes','Our branches')}</a></div></div></div></section>`;
V.leaders=()=>{const p0=S.leaders[0];return ph('choeur2',T('Nos leaders','Our leaders'),T('Celles et ceux qui veillent sur la maison.','The people who watch over the house.'))+`<section class="sec"><div class="wrap"><div class="pastor"><div class="fr"${rv('clip')}><img loading="lazy" src="${IMG}${p0[0]}.jpg" alt="${p0[1]}"></div><div${rv('right')}><span class="kick">${T(p0[2],p0[3])}</span><h2>${p0[1]}</h2><p class="lead" style="margin-top:12px">${T('Avec une équipe de seize responsables, il veille sur la vie de l’église à Ellicott City et sur ses annexes.','With a team of sixteen leaders, he watches over the life of the church in Ellicott City and its branches.')}</p></div></div><div class="pp">${S.leaders.slice(1).map((p,i)=>`<article class="pc" tabindex="0"${rv('up',(i%4)*80)}><img loading="lazy" src="${IMG}${p[0]}.jpg" alt="${p[1]}"><div><b>${p[1]}</b><span>${T(p[2],p[3])}</span></div></article>`).join('')}</div></div></section>`};
const mapHref=q=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q);
V.annexes=()=>ph('danse2',T('Nos annexes','Our branches'),T('Une famille, trois maisons.','One family, three houses.'))+`<nav class="anx-n" aria-label="${T('Nos annexes','Our branches')}"><div class="wrap"><div class="chips" style="margin:0">${S.houses.map(h=>`<button class="chip" data-goto="anx-${h.id}">${I.pin}${h[S.lang]}</button>`).join('')}</div></div></nav>`+S.houses.map((h,i)=>{const lieu=S.lang==='en'&&h.lieuEn?h.lieuEn:h.lieu;return `<section class="sec ${i%2?'mist':''}" id="anx-${h.id}"><div class="wrap"><div class="split ${i%2?'rev':''}" style="align-items:start"><div class="fr anx-p"${rv('clip')}><img loading="lazy" src="${IMG}${h.img}.jpg" alt="${h[S.lang]}"></div><div><span class="kick"${rv('up')}>${T(h.rf,h.re)}</span><h2 data-rv="words">${h[S.lang]}</h2><p class="lead" style="margin-top:12px"${rv('up',160)}>${T(h.dfr,h.den)}</p><ul class="anx-i"${rv('up',240)}><li><span class="ico">${I.pin}</span><div><small>${T('Localisation','Location')}</small><b>${lieu}</b></div></li>${h.who?`<li><span class="ico">${I.pray}</span><div><small>${T('Responsables','Leaders')}</small><b>${h.who}</b></div></li>`:''}<li><span class="ico">${I.phone}</span><div><small>${T('Téléphone','Phone')}</small><b><a href="tel:${h.tel.replace(/[^+\d]/g,'')}">${h.tel}</a></b></div></li></ul>${h.prog.length?`<div class="anx-g"${rv('up',300)}><small>${T('Rendez-vous','Gatherings')}</small><div class="anx-c">${h.prog.map(p=>`<span><b>${T(p[0],p[1])}</b>${T(p[2],p[3])}</span>`).join('')}</div></div>`:''}<div class="btns" style="margin-top:20px"${rv('up',360)}><a class="btn" href="${mapHref(h.map)}" target="_blank" rel="noopener">${T('Itinéraire','Directions')} ${arrow}</a><a class="btn line" href="tel:${h.tel.replace(/[^+\d]/g,'')}">${T('Appeler','Call')}</a></div></div></div><div class="map anx-m"${rv('up')}><iframe title="${T('Carte','Map')} : ${h[S.lang]}" data-map="https://maps.google.com/maps?q=${encodeURIComponent(h.map)}&z=${h.z}&output=embed"></iframe></div></div></section>`}).join('');
V.activites=()=>ph('danse2',T('Activités et événements','Activities and events'),T('Les rendez-vous de la semaine et les grands moments de l’église.','Weekly gatherings and the great moments of the church.'))+actSec(false)+eventsSec('page');
const artView=()=>store.get('mfci-view')==='list'?'list':'grid';
const IC_G='<svg viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><rect x="2" y="2" width="7" height="7" rx="1.800"/><rect x="11" y="2" width="7" height="7" rx="1.800"/><rect x="2" y="11" width="7" height="7" rx="1.800"/><rect x="11" y="11" width="7" height="7" rx="1.800"/></svg>',IC_L='<svg viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><rect x="2" y="3" width="4" height="4" rx="1.200"/><rect x="8" y="4" width="10" height="2" rx="1"/><rect x="2" y="8" width="4" height="4" rx="1.200"/><rect x="8" y="9" width="10" height="2" rx="1"/><rect x="2" y="13" width="4" height="4" rx="1.200"/><rect x="8" y="14" width="10" height="2" rx="1"/></svg>';
V.articles=()=>{const vw=artView();return ph('dimanche','Articles',T('Les messages partagés au sein de l’église.','Messages shared within the church.'))+`<section class="sec mist"><div class="wrap"><div class="vt"${rv('up')}><span>${S.articles.length} ${T('articles','articles')}</span><div class="vt-s" role="group" aria-label="${T('Affichage','View')}"><button data-view="grid" class="${vw==='grid'?'on':''}" aria-pressed="${vw==='grid'}" aria-label="${T('Affichage en icônes','Grid view')}" title="${T('Icônes','Grid')}">${IC_G}</button><button data-view="list" class="${vw==='list'?'on':''}" aria-pressed="${vw==='list'}" aria-label="${T('Affichage en liste','List view')}" title="${T('Liste','List')}">${IC_L}</button></div></div><div class="acards ${vw==='list'?'list':''}" id="acards">${S.articles.map((a,i)=>`<article class="ac2"${rv('up',i*90)}><a class="ac2-l" href="#/articles/${a.slug}"><div class="ac2-i"><img loading="lazy" src="${HERO}${ARTIMG[a.slug]}.jpg" alt=""><span class="crt"><span>${T("Lire l'article",'Read the article')} →</span></span></div><div class="t"><small>${a.ref}</small><h3><span class="ul">${a[S.lang]}</span></h3><p>${a.ex[S.lang]}</p><span class="more" style="margin-top:6px">${T('Lire','Read')} ${arrow}</span></div></a><div class="ac2-s">${share(a[S.lang],'articles/'+a.slug)}</div></article>`).join('')}</div></div></section>`};
V.article=slug=>{const a=S.articles.find(x=>x.slug===slug)||S.articles[0],b=a.body[S.lang];return ph(ARTIMG[a.slug],a[S.lang],a.ref,`<a href="#/">${T('Accueil','Home')}</a><span>/</span><a href="#/articles">Articles</a><span>/</span><span>${a[S.lang]}</span>`)+`<section class="sec"><div class="wrap art"><div class="art-b"${rv()}><p>${b[0]}</p><blockquote class="q">${a.ex[S.lang]}</blockquote>${b.slice(1).map(p=>`<p>${p}</p>`).join('')}<div style="margin-top:28px;padding-top:18px;box-shadow:0 -1px 0 var(--rule)">${share(a[S.lang],'articles/'+a.slug,true)}</div></div><aside${rv('right',120)}><p style="font-weight:700;margin-bottom:12px">${T('À lire aussi','Read also')}</p>${S.articles.filter(x=>x!==a).map(artRow).join('')}</aside></div></section>`};
V.albums=()=>{const cls=i=>{const k=i%9;return k===0?'a-b':k===8?'a-br':(k===6||k===7)?'a-s a-l':'a-s'};return ph('dimanche',T('Albums photos','Photo albums'),T('La vie de l’église en images.','Church life in pictures.'))+`<section class="sec"><div class="wrap">${medTabs('albums')}<div class="alb">${S.albums.map((a,i)=>albCard(a,cls(i),(i%3)*70)).join('')}</div></div></section>`};
function packAlbum(sp){const C=innerWidth<700?2:4,grid=[],size=c=>c==='big'?[2,2]:c==='tall'?[1,2]:c==='wide'?[2,1]:[1,1],pos=[];const free=(r,c,w,h)=>{for(let y=r;y<r+h;y++){grid[y]=grid[y]||Array(C).fill(0);for(let x=c;x<c+w;x++)if(x>=C||grid[y][x])return false}return true};
 sp.forEach(k=>{const [w,h]=size(k);outer:for(let r=0;;r++)for(let c=0;c<=C-w;c++){grid[r]=grid[r]||Array(C).fill(0);if(free(r,c,w,h)){for(let y=r;y<r+h;y++){grid[y]=grid[y]||Array(C).fill(0);for(let x=c;x<c+w;x++)grid[y][x]=1}pos.push({r,c,w,h});break outer}}});
 const res={};if(!pos.length)return res;const lastR=grid.length-1,row=grid[lastR];let i=pos.length-1;while(i>=0&&!(pos[i].r+pos[i].h-1===lastR))i--;if(i>=0){const it=pos[i];let w=it.w,x=it.c+it.w;while(x<C&&!row[x]&&(it.h===1)){w++;x++}if(w!==it.w)res[i]=w}return res}
V.album=id=>{const a=S.albums.find(x=>x.id===+id)||S.albums[0],i0=S.albums.indexOf(a),nx=S.albums[(i0+1)%S.albums.length];S._sets.alb=a.photos.map(p=>ALB+p[0]);const span=(p,i)=>{const r=p[2]/p[1];if(i===0)return 'big';if(r>1.15)return 'tall';if(r<.85&&i%3===2)return 'wide';return ''};
 const L=packAlbum(a.photos.map(span));return ph(ALB+'a'+a.id+'-c.jpg',a[S.lang],T(`${a.count} photo${a.count>1?'s':''} dans cet album.`,`${a.count} photo${a.count>1?'s':''} in this album.`),`<a href="#/">${T('Accueil','Home')}</a><span>/</span><a href="#/albums">${T('Albums photos','Photo albums')}</a><span>/</span><span>${a[S.lang]}</span>`)+`<section class="sec"><div class="wrap"><div class="alb-bar"><span>${T('Partagez ces photos avec vos proches.','Share these photos with your loved ones.')}</span><button class="btn line" data-albshare="${a.id}">${I.share}${T('Partager cet album','Share this album')}</button></div><div class="mo dense">${a.photos.map((p,i)=>`<button class="mo-i plain ${span(p,i)}" style="${L[i]?'grid-column:span '+L[i]+';':''}--d:${(i%4)*60}ms" data-rv="zoom" data-lbs="alb" data-lb="${i}" aria-label="${T('Agrandir la photo','Enlarge photo')} ${i+1}"><img loading="lazy" src="${ALB}${p[0]}" alt=""><span class="mo-z">${I.zoom}</span></button>`).join('')}</div>${a.count>a.photos.length?`<p class="muted" style="margin-top:14px;font-size:14.5px">${T(`${a.photos.length} photos chargées dans cette maquette sur ${a.count}.`,`${a.photos.length} of ${a.count} photos loaded in this mock-up.`)}</p>`:''}<div class="btns" style="margin-top:26px;justify-content:space-between"><a class="btn line" href="#/albums">${T('Tous les albums','All albums')}</a><a class="btn" href="#/albums/${nx.id}">${T('Album suivant','Next album')} ${arrow}</a></div></div></section>`};
const vcard=(v,i)=>`<button class="vc"${rv('up',(i%3)*80)} data-vgo="${v.id}"><div class="vc-i"><img loading="lazy" src="https://i.ytimg.com/vi/${v.id}/hqdefault.jpg" alt=""><span class="vc-p">${I.play}<em>${T('Regarder','Watch')}</em></span><span class="vc-l"></span></div><b>${v.fr}</b><small>${v.d}</small></button>`;
V.videos=()=>{const f=S._vcat||'all',list=S.videos.filter(v=>f==='all'||v.cat===f);return ph('choeur',T('Vidéos','Videos'),T('Prédications, louanges et exhortations.','Sermons, worship and exhortations.'))+`<section class="sec navy" id="vtop"><div class="wrap">${player(S.videos.slice(0,6))}</div></section><section class="sec"><div class="wrap">${medTabs('videos')}<div class="chips">${S.vcats.map(c=>`<button class="chip${f===c[0]?' on':''}" data-vcat="${c[0]}">${T(c[1],c[2])}</button>`).join('')}</div><div class="vg">${list.map(vcard).join('')}</div><a class="btn line" style="margin-top:28px" href="${S.contact.youtube}" target="_blank" rel="noopener">${T('Voir la chaîne YouTube','See the YouTube channel')} ${arrow}</a></div></section>`};
V.temoignages=()=>{const L=[{id:'WaCwsfq6ehU',fr:'Exhortation du dimanche',d:'29 janvier 2023'},{id:'5YUYYJk6g8k',fr:'You are worthy of Lord',d:'Mission For Christ International'}];return ph('priere3',T('Témoignages','Testimonies'),T('Ce que Dieu fait dans nos vies.','What God is doing in our lives.'))+`<section class="sec navy"><div class="wrap">${player(L)}</div></section><section class="sec"><div class="wrap">${medTabs('temoignages')}<div class="split"><div${rv('left')}><h2>${T('Partagez votre témoignage','Share your testimony')}</h2><p class="lead" style="margin:12px 0 18px">${T('Dieu a agi dans votre vie ? Écrivez-nous, votre histoire peut encourager quelqu’un.','Has God worked in your life? Write to us, your story may encourage someone.')}</p><a class="btn" href="${S.contact.whatsapp}" target="_blank" rel="noopener">${T('Écrire sur WhatsApp','Message on WhatsApp')} ${arrow}</a></div><span class="todo"${rv('right')}>${T("Ces deux vidéos sont celles correctement publiées aujourd'hui. Les autres liens de la page actuelle sont à corriger dans l'admin.",'These two videos are the ones correctly published today. The other links on the current page need fixing in the admin area.')}</span></div></div></section>`};
const giveBox=()=>`<div class="give" data-give${rv('right',100)}><h2 style="font-size:clamp(24px,2.6vw,32px)">${T('Votre don','Your gift')}</h2><p class="gl">${T('Choisissez un montant','Choose an amount')}</p><div class="opts">${[25,50,100,250].map(a=>`<button class="opt" data-amt="${a}">${a} $</button>`).join('')}</div><label class="amt-o"><span class="cur-s">$</span><input data-amt-input type="number" inputmode="decimal" min="1" step="1" placeholder="${T('Ou saisissez votre montant','Or enter your amount')}" aria-label="${T('Votre montant en dollars','Your amount in dollars')}"></label><p class="gl">${T('Fréquence','Frequency')}</p><div class="opts" style="margin-top:6px"><button class="opt" data-freq="once">${T('Une fois','One time')}</button><button class="opt" data-freq="month">${T('Chaque mois','Monthly')}</button></div><p class="fh" data-freq-help></p><button class="btn gold" data-give-go></button><div class="pays"><span>Visa</span><span>Mastercard</span><span>PayPal</span><span>Apple Pay</span><span>Google Pay</span></div><p class="fine">${T("Démonstration : aucun paiement n'est effectué. Le paiement réel se fera sur la page sécurisée du prestataire.",'Demo: no payment is taken. Real payment will happen on the provider’s secure page.')}</p></div>`;
