/* ---------- Rendu ---------- */
function route(){const h=(location.hash||'#/').replace(/^#\/?/,''),[a,b]=h.split('/');if(!a)return home();if(a==='articles'&&b)return V.article(b);if(a==='albums'&&b)return V.album(b);return (V[a]||home)()}
const TITLES={presentation:['Présentation','About us'],leaders:['Nos leaders','Leaders'],annexes:['Nos annexes','Branches'],activites:['Activités','Activities'],articles:['Articles','Articles'],albums:['Albums photos','Photo albums'],videos:['Vidéos','Videos'],temoignages:['Témoignages','Testimonies'],don:['Don','Give'],contact:['Contact','Contact']};
const skC=(n,c)=>Array(n).fill(`<div class="sk-c ${c||''}"><div class="sk sk-i"></div><div class="sk sk-l"></div><div class="sk sk-l s"></div></div>`).join('');
