/* ---------- Effets ---------- */
let pxEls=[],lastIO=null;
function initFx(){if(lastIO)lastIO.disconnect();$$('[data-rv="words"]').forEach(el=>{if(el.dataset.split)return;el.dataset.split=1;const tx=el.textContent.trim();el.setAttribute('aria-label',tx);el.innerHTML=tx.split(/\s+/).map((w,i)=>`<span class="w" aria-hidden="true"><span style="--w:${i}">${w}</span></span>`).join(' ')});
 const els=$$('[data-rv]');if(!('IntersectionObserver' in window)){els.forEach(e=>e.classList.add('in'))}else{const clips=new Map();lastIO=new IntersectionObserver(en=>en.forEach(x=>{if(x.isIntersecting){const list=clips.get(x.target);if(list){list.forEach(c=>c.classList.add('in'));clips.delete(x.target)}if(x.target.dataset.rv)x.target.classList.add('in');lastIO.unobserve(x.target)}}),{rootMargin:'0px 0px -6% 0px',threshold:.05});els.forEach(e=>{if(e.dataset.rv==='clip'){const p=e.parentElement;if(!clips.has(p))clips.set(p,[]);clips.get(p).push(e);lastIO.observe(p)}else lastIO.observe(e)})}
 pxEls=(reduced||!matchMedia('(pointer:fine)').matches)?[]:$$('[data-px]');
 const st=$$('[data-stat]');if(!reduced&&'IntersectionObserver' in window){st.forEach(s=>{const b=$('[data-count]',s),ds=[...b.dataset.count];b.setAttribute('aria-label',b.dataset.count);b.innerHTML=ds.map((d,i)=>`<span class="od" aria-hidden="true"><span class="od-c" style="--to:${20+ +d};--i:${ds.length-1-i}">${[...Array(30).keys()].map(n=>`<i>${n%10}</i>`).join('')}</span></span>`).join('')});const io=new IntersectionObserver(en=>en.forEach(x=>{if(!x.isIntersecting)return;io.unobserve(x.target);x.target.classList.add('on')}),{threshold:.5});st.forEach(s=>io.observe(s))}}
function onScroll(){const y=scrollY,h=document.documentElement.scrollHeight-innerHeight,hd=$('#hd');if(hd){if(y>70)hd.classList.add('small');else if(y<14)hd.classList.remove('small')}const pr=$('#prog');if(pr)pr.style.transform=`scaleX(${h>0?Math.min(1,y/h):0})`;const tp=$('#top');if(tp){tp.classList.toggle('on',y>420);const r=$('#ring');if(r)r.style.strokeDashoffset=138.2*(1-(h>0?Math.min(1,y/h):0))}
 pxEls.forEach(el=>{const b=el.parentElement.getBoundingClientRect();if(b.bottom<0||b.top>innerHeight)return;const c=(b.top+b.height/2-innerHeight/2)/innerHeight;el.style.transform=`translate3d(0,${(c*-7).toFixed(2)}%,0)`})}
let tick=false;addEventListener('scroll',()=>{if(!tick){tick=true;requestAnimationFrame(()=>{tick=false;onScroll()})}},{passive:true});addEventListener('resize',onScroll);
function initLx(){const r=$('#lx');if(!r)return;const it=$$('.lx-i',r);let tm;const size=()=>{if(!r.isConnected){removeEventListener('resize',size);return}const G=2.7,W=r.clientWidth-12*(it.length-1);r.style.setProperty('--lxw',Math.round(W*G/(G+it.length-1))+'px')};size();addEventListener('resize',size);const set=e=>{if(innerWidth<700)return;it.forEach(i=>i.classList.toggle('on',i===e))};it.forEach(i=>{i.addEventListener('pointerenter',e=>{if(e.pointerType!=='mouse')return;clearTimeout(tm);tm=setTimeout(()=>set(i),90)});i.addEventListener('focus',()=>set(i))});r.addEventListener('pointerleave',()=>clearTimeout(tm))}
function initAct(){const p=$('#acp');if(!p)return;const set=id=>{$$('img[data-ai]',p).forEach(i=>i.classList.toggle('on',i.dataset.ai===id));$$('.ac-r').forEach(r=>r.classList.toggle('act',r.dataset.act===id))};$$('.ac-r').forEach(r=>{r.addEventListener('pointerenter',()=>set(r.dataset.act));r.addEventListener('focus',()=>set(r.dataset.act))});const first=S.upcoming(1)[0].it.id;set(first)}
function toast(m){let t=$('.toast');if(!t){t=document.createElement('div');t.className='toast';t.setAttribute('role','status');document.body.appendChild(t)}t.textContent=m;t.classList.add('on');clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove('on'),4200)}
function initGive(){$$('[data-give]').forEach(g=>{let amt=50,fq='once',own=false;const inp=$('[data-amt-input]',g),hp=$('[data-freq-help]',g),fmtA=v=>Number.isInteger(v)?String(v):v.toFixed(2);const paint=()=>{const ok=amt>=1;$$('[data-amt]',g).forEach(b=>b.classList.toggle('on',!own&&+b.dataset.amt===amt));$$('[data-freq]',g).forEach(b=>b.classList.toggle('on',b.dataset.freq===fq));$$('[data-give-go]',g).forEach(b=>{b.disabled=!ok;b.textContent=!ok?T('Saisissez un montant','Enter an amount'):S.lang==='en'?`Give $${fmtA(amt)}${fq==='month'?' monthly':''}`:`Donner ${fmtA(amt)} $${fq==='month'?' par mois':''}`});if(hp)hp.textContent=fq==='month'?T('Votre carte est débitée automatiquement chaque mois. Vous pouvez arrêter à tout moment.','Your card is charged automatically every month. You can stop at any time.'):T('Un seul paiement, sans engagement.','A single payment, with no commitment.')};paint();if(inp)inp.addEventListener('input',()=>{const v=parseFloat(inp.value);own=inp.value!=='';amt=own?(v>0?Math.round(v*100)/100:0):50;paint()});g.addEventListener('click',e=>{const a=e.target.closest('[data-amt]'),f=e.target.closest('[data-freq]');if(a){amt=+a.dataset.amt;own=false;if(inp)inp.value='';paint()}if(f){fq=f.dataset.freq;paint()}if(e.target.closest('[data-give-go]'))toast(T('Démonstration : la page de paiement sécurisée (carte, PayPal, Apple Pay) s’ouvrira ici.','Demo: the secure payment page (card, PayPal, Apple Pay) will open here.'))})})}

/* ---------- Visionneuse et vidéos ---------- */
let lbSet=[],lbI=0;
function lbShow(i){lbI=(i+lbSet.length)%lbSet.length;let l=$('.lb');if(!l){l=document.createElement('div');l.className='lb';l.setAttribute('role','dialog');l.setAttribute('aria-modal','true');document.body.appendChild(l)}
 l.innerHTML=`<span class="lb-c">${lbI+1} / ${lbSet.length}</span><button class="x" aria-label="${T('Fermer','Close')}">×</button>${lbSet.length>1?`<button class="pv" aria-label="${T('Précédente','Previous')}">‹</button><button class="nx" aria-label="${T('Suivante','Next')}">›</button>`:''}<div class="lb-m"><img src="${lbSet[lbI]}" alt=""></div>${lbSet.length>1?`<div class="lb-s">${lbSet.map((s,k)=>`<button class="${k===lbI?'on':''}" data-lbt="${k}" aria-label="Photo ${k+1}"><img src="${s}" alt=""></button>`).join('')}</div>`:''}`;l.classList.add('on');const on=$('.lb-s .on',l);if(on)on.scrollIntoView({inline:'center',block:'nearest'});const x=$('.x',l);if(x)x.focus({preventScroll:true})}
function lbClose(){const l=$('.lb');if(l){l.classList.remove('on');l.innerHTML=''}}
function vidSet(root,id,play){const v=S.videos.find(x=>x.id===id)||{fr:'',d:''},sc=$('[data-vscreen]',root);sc.dataset.vscreen=id;sc.classList.remove('playing');sc.innerHTML=`<img src="https://i.ytimg.com/vi/${id}/hqdefault.jpg" alt=""><button class="vp-b" data-vplay aria-label="${T('Lire la vidéo','Play video')}">${I.play}</button>`;const item=$(`[data-vs="${id}"]`,root);$$('.vi',root).forEach(b=>b.classList.toggle('on',b===item));const tt=item?$('b',item).textContent:v.fr,dd=item?$('small',item).textContent:v.d;$('[data-vt]',root).textContent=tt;$('[data-vd]',root).textContent=dd;if(play)vidPlay(sc)}
function vidPlay(sc){sc.classList.add('playing');sc.innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${sc.dataset.vscreen}?autoplay=1&rel=0" title="${T('Vidéo','Video')}" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`}
document.addEventListener('click',e=>{const t=e.target;
 if(t.closest('[data-popx]')||(t.id==='pop')){popupClose();if(!t.closest('a'))return}
 const as=t.closest('[data-albshare]');if(as){e.preventDefault();albShare(as.dataset.albshare);return}
 const cp=t.closest('[data-copy]');if(cp){const v=cp.dataset.copy;(navigator.clipboard?navigator.clipboard.writeText(v):Promise.reject()).then(()=>toast(T('Lien copié.','Link copied.'))).catch(()=>toast(v));return}
 const nt=t.closest('[data-native]');if(nt){navigator.share({title:nt.dataset.title,url:nt.dataset.native}).catch(()=>{});return}
 if(t.closest('[data-menu]')){document.documentElement.classList.toggle('menu-open');return}
 if(t.closest('.drawer a'))document.documentElement.classList.remove('menu-open');
 if(t.classList&&t.classList.contains('drawer'))document.documentElement.classList.remove('menu-open');
 const lg=t.closest('[data-lang]');if(lg){S.lang=lg.dataset.lang;store.set('mfci-lang',S.lang);render(true);return}
 if(t.closest('#top')){window.scrollTo({top:0,behavior:reduced?'auto':'smooth'});return}
 const gt=t.closest('[data-goto]');if(gt){const el=document.getElementById(gt.dataset.goto);if(el)el.scrollIntoView({behavior:reduced?'auto':'smooth'});return}
 const vw=t.closest('[data-view]');if(vw){const v=vw.dataset.view,g=$('#acards');store.set('mfci-view',v);$$('[data-view]').forEach(b=>{b.classList.toggle('on',b===vw);b.setAttribute('aria-pressed',b===vw)});g.classList.add('sw');setTimeout(()=>{g.classList.toggle('list',v==='list');g.classList.remove('sw')},reduced?0:180);return}
 const vp=t.closest('[data-vplay]');if(vp){vidPlay(vp.closest('[data-vscreen]'));return}
 const vs=t.closest('[data-vs]');if(vs){vidSet(vs.closest('[data-player]'),vs.dataset.vs,false);return}
 const vg=t.closest('[data-vgo]');if(vg){const root=$('[data-player]');vidSet(root,vg.dataset.vgo,true);$('#vtop').scrollIntoView({behavior:reduced?'auto':'smooth'});return}
 const vc=t.closest('[data-vcat]');if(vc){S._vcat=vc.dataset.vcat;render(true);return}
 const lb=t.closest('[data-lb]');if(lb){lbSet=S._sets[lb.dataset.lbs]||[];lbShow(+lb.dataset.lb);return}
 const lt=t.closest('[data-lbt]');if(lt){lbShow(+lt.dataset.lbt);return}
 if(t.closest('.lb .x')||(t.classList&&t.classList.contains('lb-m'))){lbClose();return}
 if(t.closest('.lb .pv')){lbShow(lbI-1);return}if(t.closest('.lb .nx')){lbShow(lbI+1);return}
});
let lbx=null;document.addEventListener('pointerdown',e=>{if(e.target.closest('.lb-m'))lbx=e.clientX});document.addEventListener('pointerup',e=>{if(lbx===null)return;const d=e.clientX-lbx;lbx=null;if(Math.abs(d)>50)lbShow(lbI+(d<0?1:-1))});
document.addEventListener('submit',e=>{const f=e.target.closest('[data-demo]');if(f){e.preventDefault();toast(f.dataset.demo==='news'?T('Démonstration : aucune inscription n’est enregistrée.','Demo: no sign-up is saved.'):T('Démonstration : aucun message n’est envoyé.','Demo: no message is sent.'))}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){lbClose();popupClose();document.documentElement.classList.remove('menu-open')}if(e.key==='Tab'&&$('#pop.on')){const f=$$('#pop a,#pop button,#pop input'),a=document.activeElement;if(e.shiftKey&&a===f[0]){e.preventDefault();f[f.length-1].focus()}else if(!e.shiftKey&&a===f[f.length-1]){e.preventDefault();f[0].focus()}}if($('.lb.on')){if(e.key==='ArrowLeft')lbShow(lbI-1);if(e.key==='ArrowRight')lbShow(lbI+1)}});
